# Vendored release toolkit; change the toolkit source, then render again.
# ruff: noqa
# mypy: ignore-errors
# pylint: skip-file
# fmt: off
"""Reject ambiguous workflows and mutable generated action references."""

import importlib.util
import json
import tempfile
import unittest
from pathlib import Path

import yaml

ROOT = Path(__file__).resolve().parents[2]
SPEC = importlib.util.spec_from_file_location(
    "workflow_contracts", ROOT / "scripts/workflow_contracts.py"
)
if SPEC is None or SPEC.loader is None:
    raise RuntimeError("Cannot load workflow contract checks")
CONTRACTS = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(CONTRACTS)
SHA = "a" * 40
MARKER = (
    "# Generated by venus-os-ci-toolkit/scripts/install_release.py; edit .release-policy.json.\n"
)


class WorkflowYAMLTests(unittest.TestCase):
    """Exercise real parsing and the generator/consumer boundary."""

    def test_duplicate_top_level_and_nested_keys_are_rejected(self):
        for source in ("jobs: {}\njobs: {}", "jobs:\n  test:\n    uses: one\n    uses: two"):
            with self.subTest(source=source), self.assertRaises(ValueError):
                yaml.load(source, Loader=CONTRACTS.UniqueKeyLoader)  # nosec B506 - BaseLoader subclass, no object construction

    def test_yaml_trigger_keys_and_scalars_remain_strings(self):
        result = yaml.load("on: push\nvalue: true\n", Loader=CONTRACTS.UniqueKeyLoader)  # nosec B506 - BaseLoader subclass, no object construction
        self.assertEqual(result, {"on": "push", "value": "true"})

    def test_release_gate_cannot_ignore_job_or_command_failure(self):
        source = """name: CI gate
if: ${{ always() }}
steps:
  - run: python3 scripts/release_validation.py gate --channel "$RELEASE_CHANNEL"
    env:
      RESULTS: ${{ toJSON(needs) }}
      RELEASE_CHANNEL: ${{ inputs.channel }}
"""
        for scope in ("job", "step"):
            for value in (None, "false", "true", "${{ inputs.ignore_failure }}"):
                with self.subTest(scope=scope, value=value):
                    gate = yaml.load(source, Loader=CONTRACTS.UniqueKeyLoader)  # nosec B506
                    target = gate if scope == "job" else gate["steps"][0]
                    if value is not None:
                        target["continue-on-error"] = value
                    if value in (None, "false"):
                        CONTRACTS.validate_release_gate(gate)
                    else:
                        with self.assertRaisesRegex(ValueError, "fail-closed profile gate"):
                            CONTRACTS.validate_release_gate(gate)

    def test_release_gate_command_cannot_be_conditionally_skipped(self):
        gate = {
            "name": "CI gate",
            "if": "${{ always() }}",
            "steps": [{
                "run": 'python3 scripts/release_validation.py gate --channel "$RELEASE_CHANNEL"',
                "env": {"RESULTS": "${{ toJSON(needs) }}", "RELEASE_CHANNEL": "${{ inputs.channel }}"},
            }],
        }
        CONTRACTS.validate_release_gate(gate)
        for condition in ("false", "${{ false }}", "${{ inputs.run_gate }}", "${{ success() }}"):
            with self.subTest(condition=condition):
                gate["steps"][0]["if"] = condition
                with self.assertRaisesRegex(ValueError, "fail-closed profile gate"):
                    CONTRACTS.validate_release_gate(gate)

    def test_release_gate_rejects_step_and_inherited_execution_overrides(self):
        cases = ((scope, key, value) for scope in ("step", "job", "workflow")
                 for key, value in (("shell", "bash -c 'exit 0' {0}"), ("working-directory", "other")))
        for scope, key, value in cases:
            gate = {
                "name": "CI gate", "if": "${{ always() }}",
                "steps": [{
                    "run": 'python3 scripts/release_validation.py gate --channel "$RELEASE_CHANNEL"',
                    "env": {"RESULTS": "${{ toJSON(needs) }}", "RELEASE_CHANNEL": "${{ inputs.channel }}"},
                }],
            }
            workflow = {"jobs": {"gate": gate}}
            CONTRACTS.validate_release_gate(gate, workflow)
            if scope == "step":
                target = gate["steps"][0]
            else:
                target = (gate if scope == "job" else workflow).setdefault("defaults", {}).setdefault("run", {})
            target[key] = value
            with self.subTest(scope=scope, key=key), self.assertRaisesRegex(ValueError, "cannot override its shell"):
                CONTRACTS.validate_release_gate(gate, workflow)

    def test_non_string_mapping_keys_are_rejected(self):
        with self.assertRaises(ValueError):
            yaml.load("? [one, two]\n: value", Loader=CONTRACTS.UniqueKeyLoader)  # nosec B506 - BaseLoader subclass, no object construction

    def test_mutable_or_unknown_generated_actions_are_rejected(self):
        for reference, pins in (("actions/checkout@main", None), ("actions/checkout@" + SHA, {})):
            workflow = {"jobs": {"build": {"steps": [{"uses": reference}]}}}
            with self.subTest(reference=reference), self.assertRaises(ValueError):
                CONTRACTS.validate_workflow_pins("quality-gate.yml", workflow, pins)

    def test_docker_actions_require_full_content_digest_and_preserve_manifest_checks(self):
        pinned = "docker://alpine@sha256:" + "a" * 64
        CONTRACTS.validate_action_reference("consumer.yml", pinned, None)
        for reference in ("docker://alpine:latest", "docker://alpine@" + SHA,
                          "docker://@sha256:" + "a" * 64,
                          "docker://alpine@sha256:" + "a" * 63,
                          "docker://alpine@sha256:" + "A" * 64,
                          "docker://alpine@sha512:" + "a" * 64):
            with self.subTest(reference=reference), self.assertRaises(ValueError):
                CONTRACTS.validate_action_reference("consumer.yml", reference, None)
        with self.assertRaisesRegex(ValueError, "differs from generator pins"):
            CONTRACTS.validate_action_reference("generated.yml", pinned, {})

    def test_local_steps_and_matching_manifest_are_supported(self):
        workflow = {
            "jobs": {
                "build": {
                    "steps": [
                        {"run": "true"},
                        {"uses": "./local"},
                        {"uses": "actions/checkout@" + SHA},
                    ]
                }
            }
        }
        CONTRACTS.validate_workflow_pins("quality-gate.yml", workflow, {"actions/checkout": SHA})

    def test_consumers_without_manifest_still_require_sha_and_marker(self):
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            folder = root / ".github/workflows"
            folder.mkdir(parents=True)
            path = folder / "quality-gate.yml"
            workflow = {"jobs": {"build": {"steps": [{"uses": "actions/checkout@" + SHA}]}}}
            path.write_text(MARKER)
            CONTRACTS.validate_generator_pins(root, {path.name: workflow})
            path.write_text("# marker removed\n")
            with self.assertRaises(ValueError):
                CONTRACTS.validate_generator_pins(root, {path.name: workflow})
            path.write_text(MARKER)
            workflow["jobs"]["build"]["steps"][0]["uses"] = "actions/checkout@main"
            with self.assertRaises(ValueError):
                CONTRACTS.validate_generator_pins(root, {path.name: workflow})

    def test_canonical_generator_requires_its_manifest(self):
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            (root / "scripts").mkdir()
            (root / "scripts/install_release.py").touch()
            with self.assertRaises(ValueError):
                CONTRACTS.validate_generator_pins(root, {})

    def test_manifest_mismatch_is_rejected(self):
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            folder = root / ".github/workflows"
            folder.mkdir(parents=True)
            (folder / "quality-gate.yml").write_text(MARKER)
            (root / ".github/action-pins.json").write_text(
                json.dumps([{"packageName": "actions/checkout", "digest": "b" * 40}])
            )
            workflow = {"jobs": {"build": {"steps": [{"uses": "actions/checkout@" + SHA}]}}}
            with self.assertRaises(ValueError):
                CONTRACTS.validate_generator_pins(root, {"quality-gate.yml": workflow})

    def test_reusable_workflows_require_immutable_matching_references(self):
        action = "owner/repo/.github/workflows/build.yml"
        for reference, pins in (
            (action + "@main", None),
            (action + "@v1", None),
            (action + "@" + SHA, {}),
            (action + "@" + SHA, {action: "b" * 40}),
        ):
            workflow = {"jobs": {"build": {"uses": reference}}}
            with self.subTest(reference=reference, pins=pins), self.assertRaises(ValueError):
                CONTRACTS.validate_workflow_pins("release-pipeline.yml", workflow, pins)
        workflow = {"jobs": {"build": {"uses": action + "@" + SHA}}}
        CONTRACTS.validate_workflow_pins("release-pipeline.yml", workflow, {action: SHA})
        CONTRACTS.validate_workflow_pins("release-pipeline.yml", workflow, None)
        workflow["jobs"]["build"]["uses"] = "./.github/workflows/build.yml"
        CONTRACTS.validate_workflow_pins("release-pipeline.yml", workflow, {})

    def test_configured_fuzz_workflow_requires_exact_policy_pin(self):
        action = "victron-venus/venus-os-ci-toolkit/.github/workflows/fuzz.yml"
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            folder = root / ".github/workflows"
            folder.mkdir(parents=True)
            (folder / "release-pipeline.yml").write_text(MARKER)
            (root / ".github/action-pins.json").write_text("[]")
            policy = root / ".release-policy.json"
            policy.write_text(json.dumps({"fuzzing": {"toolkit_ref": SHA}}))
            workflow = {"jobs": {"fuzz": {"uses": action + "@" + SHA, "with": {"toolkit-ref": SHA}}}}
            CONTRACTS.validate_generator_pins(root, {"release-pipeline.yml": workflow})
            for reference in (action + "@" + "b" * 40, action + "@main",
                              "other/repo/.github/workflows/fuzz.yml@" + SHA):
                workflow["jobs"]["fuzz"]["uses"] = reference
                with self.subTest(reference=reference), self.assertRaises(ValueError):
                    CONTRACTS.validate_generator_pins(root, {"release-pipeline.yml": workflow})
            for reference in ("main", "a" * 39, "A" * 40, None, 42):
                policy.write_text(json.dumps({"fuzzing": {"toolkit_ref": reference}}))
                with self.subTest(policy_reference=reference), self.assertRaises(ValueError):
                    CONTRACTS.generator_pins(root)

    def test_consumer_fuzz_pins_agree_without_generator_manifest(self):
        action = "victron-venus/venus-os-ci-toolkit/.github/workflows/fuzz.yml"
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            (root / ".github/workflows").mkdir(parents=True)
            (root / ".github/workflows/release-pipeline.yml").write_text(MARKER)
            (root / ".release-policy.json").write_text(json.dumps({"fuzzing": {"toolkit_ref": SHA}}))
            for wrapper, runtime, accepted in ((SHA, SHA, True), ("b" * 40, SHA, False),
                                               (SHA, "b" * 40, False), ("b" * 40, "b" * 40, False)):
                workflow = {"jobs": {"fuzz": {"uses": action + "@" + wrapper, "with": {"toolkit-ref": runtime}}}}
                if accepted:
                    CONTRACTS.validate_generator_pins(root, {"release-pipeline.yml": workflow})
                else:
                    with self.subTest(wrapper=wrapper, runtime=runtime), self.assertRaises(ValueError):
                        CONTRACTS.validate_generator_pins(root, {"release-pipeline.yml": workflow})

    def test_non_generated_workflows_require_sha_without_manifest_membership(self):
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            (root / ".github").mkdir()
            (root / ".github/action-pins.json").write_text(
                json.dumps([{"packageName": "actions/checkout", "digest": SHA}])
            )
            workflow = {"jobs": {"build": {"steps": [{"uses": "owner/action@" + SHA}]}}}
            CONTRACTS.validate_generator_pins(root, {"ci.yml": workflow})
            workflow["jobs"]["build"]["steps"][0]["uses"] = "owner/action@main"
            with self.assertRaises(ValueError):
                CONTRACTS.validate_generator_pins(root, {"ci.yml": workflow})
            workflow = {"jobs": {"build": {"uses": "owner/repo/.github/workflows/build.yml@main"}}}
            with self.assertRaises(ValueError):
                CONTRACTS.validate_generator_pins(root, {"other.yml": workflow})


if __name__ == "__main__":
    unittest.main()
